cpp.setup:
auto* control = new fluent::layout::PropertyPanel(%PARENT%);
fluent::layout::PropertyDefinition titleDef;
titleDef.key = QStringLiteral("title");
titleDef.label = QStringLiteral("Title");
titleDef.group = QStringLiteral("General");
titleDef.defaultValue = QStringLiteral("Quarterly report");
fluent::layout::PropertyDefinition visibleDef;
visibleDef.key = QStringLiteral("visible");
visibleDef.label = QStringLiteral("Visible");
visibleDef.group = QStringLiteral("General");
visibleDef.type = fluent::layout::PropertyDefinition::Boolean;
visibleDef.defaultValue = true;
fluent::layout::PropertyDefinition densityDef;
densityDef.key = QStringLiteral("density");
densityDef.label = QStringLiteral("Density");
densityDef.group = QStringLiteral("Layout");
densityDef.type = fluent::layout::PropertyDefinition::Choice;
densityDef.choices = {QStringLiteral("Compact"), QStringLiteral("Standard"), QStringLiteral("Comfortable")};
densityDef.defaultValue = QStringLiteral("Standard");
fluent::layout::PropertyDefinition spacingDef;
spacingDef.key = QStringLiteral("spacing");
spacingDef.label = QStringLiteral("Spacing");
spacingDef.group = QStringLiteral("Layout");
spacingDef.type = fluent::layout::PropertyDefinition::Number;
spacingDef.minimum = 0;
spacingDef.maximum = 32;
spacingDef.step = 4;
spacingDef.defaultValue = 12;
control->setProperties({titleDef, visibleDef, densityDef, spacingDef});
